<?php
include_once __DIR__.'/includes/session_check.php';require_login_modal();include __DIR__.'/db_connect.php';
$school=(int)($_SESSION['login_school_id']??0);$type=(int)($_SESSION['login_type']??0);if(!$school||$type!==1)die('No autorizado.');$autoload=__DIR__.'/vendor/autoload.php';if(!file_exists($autoload))die('PhpSpreadsheet no está instalado.');require_once $autoload;
use PhpOffice\PhpSpreadsheet\Spreadsheet;use PhpOffice\PhpSpreadsheet\Writer\Xlsx;use PhpOffice\PhpSpreadsheet\Style\Fill;
$where=['s.school_id=?'];$types='i';$params=[$school];$year=(int)($_GET['academic_year_id']??0);$level=trim($_GET['level']??'');$payment=trim($_GET['payment_status']??'');$status=trim($_GET['debt_status']??'');$due=trim($_GET['due_status']??'');$studentStatus=trim($_GET['student_status']??'');$ids=array_values(array_unique(array_filter(array_map('intval',explode(',',$_GET['ids']??'')))));if($ids)$where[]='ef.id IN('.implode(',',$ids).')';if($year){$where[]='c.academic_year_id=?';$types.='i';$params[]=$year;}if($level){$where[]='s.nivel=?';$types.='s';$params[]=$level;}if($status){$where[]='ef.debt_status=?';$types.='s';$params[]=$status;}if($studentStatus){$where[]='s.status=?';$types.='s';$params[]=$studentStatus;}if($due==='overdue')$where[]="ef.due_date<CURDATE() AND ef.debt_status='Activa'";elseif($due==='soon')$where[]="ef.due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 7 DAY)";elseif($due==='none')$where[]='ef.due_date IS NULL';
$base="SELECT ay.year,s.id_no,s.name,s.nivel,s.grado,s.seccion,c.course,ef.billing_period,ef.issue_date,ef.due_date,ef.total_fee,ef.discounted_amount,ef.debt_status,ef.cancellation_reason,(SELECT COALESCE(SUM(p.amount),0) FROM payments p WHERE p.ef_id=ef.id AND p.payment_status='Confirmado') paid,COALESCE(ef.discounted_amount,ef.total_fee) amount FROM student_ef_list ef INNER JOIN student s ON s.id=ef.student_id INNER JOIN courses c ON c.id=ef.course_id INNER JOIN academic_year ay ON ay.id=c.academic_year_id WHERE ".implode(' AND ',$where);$payWhere='';if($payment==='pending')$payWhere=' WHERE q.paid=0 AND q.amount>0';elseif($payment==='partial')$payWhere=' WHERE q.paid>0 AND q.paid<q.amount';elseif($payment==='paid')$payWhere=' WHERE q.amount>0 AND q.paid>=q.amount';elseif($payment==='exempt')$payWhere=' WHERE q.amount<=0 AND q.discounted_amount IS NOT NULL AND q.total_fee>0';$stmt=$conn->prepare("SELECT q.*,q.amount-q.paid balance FROM ($base) q$payWhere ORDER BY q.year DESC,q.name,q.course");$args=[$types];foreach($params as &$v)$args[]=&$v;call_user_func_array([$stmt,'bind_param'],$args);$stmt->execute();$r=$stmt->get_result();
$book=new Spreadsheet();$sheet=$book->getActiveSheet();$sheet->setTitle('Deudas');$headers=['Año','DNI','Estudiante','Nivel','Grado','Sección','Concepto','Periodo','Emisión','Vencimiento','Monto original','Monto final','Pagado','Saldo','Estado deuda','Estado pago','Motivo anulación'];$sheet->fromArray($headers,null,'A1');$sheet->getStyle('A1:Q1')->getFont()->setBold(true)->getColor()->setARGB('FFFFFFFF');$sheet->getStyle('A1:Q1')->getFill()->setFillType(Fill::FILL_SOLID)->getStartColor()->setARGB('FF2F6FED');$row=2;while($x=$r->fetch_assoc()){$pay=(float)$x['paid'];$amount=(float)$x['amount'];$exempt=$x['discounted_amount']!==null&&(float)$x['total_fee']>0&&$amount<=.009;$paymentStatus=$exempt?'Exonerada':($pay<=0?'Pendiente':($pay+0.001>=$amount?'Pagada':'Parcial'));$sheet->fromArray([$x['year'],$x['id_no'],$x['name'],$x['nivel'],$x['grado'],$x['seccion'],$x['course'],$x['billing_period'],$x['issue_date'],$x['due_date'],(float)$x['total_fee'],$amount,$pay,max(0,(float)$x['balance']),$x['debt_status'],$paymentStatus,$x['cancellation_reason']],null,'A'.$row++);}foreach(range('A','Q') as $column)$sheet->getColumnDimension($column)->setAutoSize(true);$sheet->freezePane('A2');$sheet->setAutoFilter('A1:Q'.max(1,$row-1));while(ob_get_level())ob_end_clean();header('Content-Type: application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');header('Content-Disposition: attachment; filename="deudas_'.date('Ymd_His').'.xlsx"');header('Cache-Control: max-age=0');(new Xlsx($book))->save('php://output');exit;
